# Hash every raw artifact; no application paths written.
manifest=[dict(path=str(f.relative_to(RUN)).replace("\\","/"),bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()) for f in sorted((RUN/'raw').rglob('*')) if f.is_file()]
(RUN/'evidence/raw-manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
initial=json.loads((RUN/'evidence/initial-state.json').read_text(encoding='utf-8'))
changed=[name for name,h in initial['existing_hashes'].items() if not (ROOT/name).exists() or hashlib.sha256((ROOT/name).read_bytes()).hexdigest()!=h]
validation=dict(existing_files_checked=len(initial['existing_hashes']),existing_files_changed=changed,branch=subprocess.check_output(['git','branch','--show-current'],cwd=ROOT,text=True).strip(),head_unchanged=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()==initial['head'],raw_files=len(manifest))
assert not changed and validation['branch']=='zyre-updates' and validation['head_unchanged']
(RUN/'evidence/validation.json').write_text(json.dumps(validation,indent=2),encoding='utf-8');print(json.dumps(validation,indent=2))
